mapper.select:
SELECT * FROM () r WHERE r.use_yn=#{use_yn}
    AND r.status=#{status}AND r.status!='퇴사'
    AND r.emp_se_cd=#{empType}
    AND (r.main_job_cd=#{job} OR EXISTS(SELECT 1 FROM mst.dev_sub_job s WHERE s.dev_id=r.dev_id AND s.job_cd=#{job}))
    AND (position(lower(#{q}) in lower(r.dev_nm))>0 OR position(lower(#{q}) in lower(r.mng_no))>0)
    ORDER BY r.dev_nm,r.dev_id
